def check_win(board):
    # Check rows
    for row in board:
        if row.count('x') == 3:
            return True
    # Check columns
    for i in range(4):
        col = [board[j][i] for j in range(4)]
        if col.count('x') == 3:
            return True
    # Check diagonals
    if board[0][0] == 'x' and board[1][1] == 'x' and board[2][2] == 'x' and board[3][3] == 'x':
        return True
    if board[0][3] == 'x' and board[1][2] == 'x' and board[2][1] == 'x' and board[3][0] == 'x':
        return True
    return False

def check_draw(board):
    for row in board:
        for cell in row:
            if cell == '.':
                return False
    return True

def check_single_turn(board):
    for row in board:
        for cell in row:
            if cell == '.':
                return True
    return False

board = []
for i in range(4):
    board.append(input())

if check_win(board):
    print("YES")
else:
    print("NO")

