def determine_result(x, y, z):
    # Handle the case where there are only one upvoter and one downvoter
    if x + y == 1:
        return "+";
    elif x + y == z:
        return "-";
    else:
        # There are more than one possible results, so report uncertainty
        return "?"

# Test the function with some examples
print(determine_result(3, 7, 0)) # Output: -
print(determine_result(2, 0, 1)) # Output: +
print(determine_result(1, 1, 0)) # Output: 0
print(determine_result(0, 0, 1)) # Output: ?

