import math

def main():
    n = int(input())
    vectors = []
    for _ in range(n):
        x, y = map(int, input().split())
        vectors.append((x, y))

    min_angle = math.pi
    min_angle_pair = (0, 1)
    for i in range(n):
        for j in range(i + 1, n):
            angle = math.acos(dot_product(vectors[i], vectors[j]) / (vector_length(vectors[i]) * vector_length(vectors[j])))
            if angle < min_angle:
                min_angle = angle
                min_angle_pair = (i + 1, j + 1)

    print(*min_angle_pair)

def dot_product(vector1, vector2):
    return vector1[0] * vector2[0] + vector1[1] * vector2[1]

def vector_length(vector):
    return math.sqrt(vector[0] ** 2 + vector[1] ** 2)

if __name__ == "__main__":
    main()

