def find_overlapping_segments(a):
    # Initialize two dictionaries to keep track of the indices of the segments that overlap with each other
    overlapping_indices = {}
    not_overlapping_indices = {}

    # Iterate through the segments and check for overlapping
    for i in range(len(a)):
        start, end = a[i]
        if start in overlapping_indices or end in overlapping_indices:
            # If the current segment overlaps with a previous segment, add the indices to the overlapping_indices dictionary
            overlapping_indices[i] = True
        else:
            # If the current segment does not overlap with any previous segment, add it to the not_overlapping_indices dictionary
            not_overlapping_indices[i] = True

    # If there are any segments that do not overlap with any other segment, print them
    if len(not_overlapping_indices) > 0:
        print("No overlapping segments found")
    else:
        # If there are any segments that overlap with each other, print them
        for i in overlapping_indices:
            print(f"Segment {i} overlaps with segment {overlapping_indices[i]}")

