def max_product(numbers):
    def product(num):
        return num if num >= 0 else -(abs(num) + 1)
    return max(reduce(lambda x, y: x*y, map(product, numbers), 1), 0)

def find_max_product_array(numbers):
    def product(num):
        return num if num >= 0 else -(abs(num) + 1)
    best_product = max_product(numbers[:])
    for i in range(len(numbers)):
        numbers[i] = product(numbers[i])
        new_product = max_product(numbers[:])
        if new_product > best_product:
            best_product = new_product
            best_array = numbers[:]
        numbers[i] = numbers[i] * -1 if numbers[i] < 0 else numbers[i]
    return best_array

print(find_max_product_array(numbers))

