def max_erase(n):
    # Initialize a list to store the maximum number of consecutive elements that can be erased
    max_erase = 0

    # Loop through the array and keep track of the maximum number of consecutive elements that can be erased
    for i in range(n):
        if i % 2 == 0:
            # If the current element is even, check if it is the last element in the array
            if i == n - 1:
                # If it is the last element, check if the array is still valid
                if all(x > 1 for x in range(i, n)):
                    # If the array is still valid, increase the maximum number of consecutive elements that can be erased
                    max_erase = max(max_erase, i)
            else:
                # If the current element is not the last element, check if the array is still valid
                if all(x > 1 for x in range(i, n)):
                    # If the array is still valid, increase the maximum number of consecutive elements that can be erased
                    max_erase = max(max_erase, i)

    return max_erase

