def max_beauty(n, x, a):
    prefix_sum = [0] * (n+1)
    for i in range(1, n+1):
        prefix_sum[i] = prefix_sum[i-1] + a[i-1]

    max_beauty = 0
    for i in range(1, n+1):
        for j in range(i, n+1):
            beauty = prefix_sum[j] - prefix_sum[i-1]
            if x != 0:
                beauty += (j-i+1) * x
            max_beauty = max(max_beauty, beauty)

    return max_beauty

