    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    zero_count = sum(1 for x in a if x == 0)

    if zero_count > k:
        return "No"

    b_set = set(b)

    for i in range(zero_count):
        if 0 in b_set:
            b_set.remove(0)
        if i < zero_count:
            b_set.add(b[i])

    b_list = list(b_set)

    for i in range(n):
        if a[i] == 0:
            if i == 0:
                if a[i] == b_list[0]:
                    b_list.remove(b_list[0])
                    b_list.insert(0, a[i])
                else:
                    return "No"
            else:
                if a[i] == b_list[i]:
                    b_list.remove(b_list[i])
                    b_list.insert(i, a[i])
                else:
                    return "No"

    if b_list == b_list[::-1]:
        return "Yes"
    else:
        return "No"

