                # Check if the frame is valid
                valid = True
                for i in range(n):
                    for j in range(m):
                        if frame[i][j] == 'w' and monitor[i][j] != 'w':
                            valid = False
                            break
                    if not valid:
                        break

                if valid:
                    return frame

