def find_frame(monitor):
    n, m = len(monitor), len(monitor[0])
    for size in range(1, min(n, m) + 1):
        for top in range(n - size + 1):
            for left in range(m - size + 1):
                frame = [['.' for _ in range(m)] for _ in range(n)]
                for i in range(size):
                    for j in range(size):
                        if (i == 0 or i == size - 1) and (j == 0 or j == size - 1):
                            frame[top + i][left + j] = '+'
                        elif i == 0 or i == size - 1:
                            frame[top + i][left + j] = '+'
                        elif j == 0 or j == size - 1:
                            frame[top + i][left + j] = '+'
                        else:
                            frame[top + i][left + j] = '.'

                # Check if the frame is valid
                valid = True
                for i in range(n):
                    for j in range(m):
                        if frame[i][j] == 'w' and monitor[i][j] != 'w':
                            valid = False
                            break
                    if not valid:
                        break

                if valid:
                    return frame

    return [-1]

