def give_baloons(n, k, baloons):
    # Create a dictionary to store the frequency of each balloon color
    freq = {}
    for color in baloons:
        if color in freq:
            freq[color] += 1
        else:
            freq[color] = 1

    # Check if it's possible to distribute the baloons such that no friend is upset
    for color in freq:
        if freq[color] > k // 2:
            return "NO"

    return "YES"

