    finger_mapping = {}

    # iterate through the phone number
    for i in range(n):
        # check if the current digit is already in the dictionary
        if phone_number[i] in finger_mapping:
            # if it is, check if the current digit is the same as the last digit in the dictionary
            if phone_number[i] == finger_mapping[phone_number[i-1]]:
                return "YES"
        else:
            # if it's not, add it to the dictionary with the current digit as the last digit
            finger_mapping[phone_number[i]] = phone_number[i-1]

    # if no matching digit is found, return "NO"
    return "NO"

