import re

def is_palindrome(time):
    pattern = r'(\d)\1'
    hours, minutes = map(int, time.split(':'))
    return bool(re.search(pattern, str(hours)) and re.search(pattern, str(minutes))) or (hours == minutes)

def next_palindrome(time):
    hours, minutes = map(int, time.split(':'))
    minutes += 1
    while minutes % 2 == 0:
        minutes += 1
    return f"{hours}:{minutes}" if is_palindrome(f"{hours}:{minutes}") else next_palindrome(str(int(time.split(':')[0]) + int(time.split(':')[1]) + 1).zfill(4))

time = input()
minutes_to_sleep = int(next_palindrome(time).split(':')[1]) - int(time.split(':')[1])
print(minutes_to_sleep)

def min_sleep(time):
    h, m = map(int, time.split(':'))
    while True:
        h = str(h).zfill(2)
        m = str(m).zfill(2)
        if h == m[::-1]:
            break
        m += 1
        if m == 60:
            m = 0
            h = str(int(h) + 1)
    return int(h + m) - int(time)

