def calculate_beauty(ribbon):
    # Helper function to calculate the beauty of a ribbon
    counts = {}
    max_beauty = 0
    current_subribbon = ''

    for char in ribbon:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1
            if len(current_subribbon) > max_beauty:
                max_beauty = len(current_subribbon)
            current_subribbon = char

    if len(current_subribbon) > max_beauty:
        max_beauty = len(current_subribbon)

    return max_beauty


def find_winner(n, ribbons):
    # Main function to find the winner
    kuro_beauty = calculate_beauty(ribbons[0])
    shiro_beauty = calculate_beauty(ribbons[1])
    katie_beauty = calculate_beauty(ribbons[2])

    max_beauty = max(kuro_beauty, shiro_beauty, katie_beauty)

