def beauty(s):
    sub = s[0]
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            sub = max(sub, count)
            count = 1
    return max(sub, count)

def solve(n, s1, s2, s3):
    if n == 0:
        return "Draw"
    if beauty(s1) > beauty(s2) and beauty(s1) > beauty(s3):
        return "Kuro"
    if beauty(s2) > beauty(s1) and beauty(s2) > beauty(s3):
        return "Shiro"
    if beauty(s3) > beauty(s1) and beauty(s3) > beauty(s2):
        return "Katie"
    return solve(n-1, s1[1:], s2[1:], s3[1:])

