from collections import Counter

def solve():
    n = int(input().strip())
    s = [input().strip() for _ in range(3)]
    c = [Counter(x) for x in s]
    m = [max(x.values()) for x in c]
    l = [len(x) for x in s]
    p = [0]*3
    for i in range(3):
        if m[i] == l[i] and n == 1:
            p[i] = m[i] - 1
        elif m[i] == l[i] and n > 1:
            p[i] = m[i]
        elif m[i] < l[i] and n >= l[i] - m[i]:
            p[i] = l[i]
        else:
            p[i] = m[i] + min(n, l[i] - m[i])
    if p.count(max(p)) > 1:
        print("Draw")
    else:
        print(["Kuro", "Shiro", "Katie"][p.index(max(p))])

