def max_beauty(ribbons, n):
    lengths = len(ribbons[0])
    max_beauty_dict = {cat: [0, set()] for cat in ['Kuro', 'Shiro', 'Katie']}

    for cat, ribbon in enumerate(ribbons):
        counts = [0] * 52  # 26 for uppercase, 26 for lowercase
        for char in ribbon:
            counts[ord(char.lower()) - ord('a')] += 1
        for i in range(26):
            max_beauty_dict[cat][0] = max(max_beauty_dict[cat][0], counts[i])
            max_beauty_dict[cat][1].add(i)

    max_beauty_after_n = [max_beauty_dict[cat][0] + min(n, lengths - max_beauty_dict[cat][0]) for cat in max_beauty_dict]

    if max_beauty_after_n.count(max_beauty_after_n[0]) == 1:
        return max_beauty_after_n.index(max_beauty_after_n[0]) + 1
    else:
        return 'Draw'

