def max_painted_sections(n, q, painters):
    painters.sort(key=lambda x: x[0])
    max_painted = 0

    for i in range(q):
        for j in range(i+1, q):
            painted = 0
            for k in range(n):
                for l, r in [painters[i], painters[j]]:
                    if l <= k+1 <= r:
                        painted += 1
                        break
            max_painted = max(max_painted, painted)

    return max_painted

