                elif b[j] == 4:
                    count_4[4] += 1
                # If the other student's academic performance is 5, add them to the count for that performance
                elif b[j] == 5:
                    count_5[5] += 1

    # If the number of students with each academic performance is equal in both groups, return the number of exchanges
    if count_1 == count_2:
