def is_reachable(n, h_directions, v_directions):
    # Create a graph with n*m nodes numbered from 0 to n*m-1
    grid_size = n * m
    graph = [[-1] * grid_size for _ in range(grid_size)]

    # Populate the graph with directions
    for i in range(n):
        if h_directions[i] == '>':
            for j in range(m):
                graph[i*m+j][(i+1)*m+j] = 1
                graph[(i+1)*m+j][i*m+j] = 1
        else:
            for j in range(m):
                graph[i*m+j][(i+1)*m+j] = 1
                graph[(i+1)*m+j][i*m+j] = 1

    for j in range(m):
        if v_directions[j] == '^':
            for i in range(n-1):
                graph[i*m+j][(i+1)*m+j+1] = 1
                graph[(i+1)*m+j+1][i*m+j] = 1
        else:
            for i in range(n-1):
                graph[i*m+j][(i+1)*m+j+1] = 1
                graph[(i+1)*m+j+1][i*m+j] = 1

    # Perform a Depth First Search from each node to check if all nodes are reachable
    visited = [False] * grid_size
    for i in range(grid_size):
        if not visited[i] and dfs(i, graph, visited):
            return True

    return False

def dfs(node, graph, visited):
    visited[node] = True
    for neighbor in get_neighbors(node, graph, n, m):
        if not visited[neighbor]:
            if dfs(neighbor, graph, visited):
                return True

    return False

def get_neighbors(node, graph, n, m):
    i, j = node // m, node % m
    neighbors = []
    if i > 0:
        neighbors.append(node - m)
    if i < n-1:
        neighbors.append(node + m)
    if j > 0:
        neighbors.append(node - 1)
    if j < m-1:
        neighbors.append(node + 1)

    return neighbors

