def is_mirror_word(word):
    # Create a dictionary to store the frequency of characters in the word
    freq = {}
    for char in word:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # Check if the frequency of each character is equal to its mirror character's frequency
    for char in freq:
        if char.isalpha():
            mirror_char = char.upper()[::-1]
            if char != mirror_char:
                return "NO"
            if freq[char] != freq[mirror_char]:
                return "NO"

    return "YES"

