def can_sort_rows(n, m, table):
    # Check if the first row is already sorted
    if table[0] != list(range(1, m+1)):
        return "NO"

    # Check if any column is already sorted
    for col in range(m):
        if all(row[col] == col + 1 for row in table):
            return "YES"

    # Try to swap columns to sort the first row
    for i in range(1, m):
        if table[0][i] != i + 1:
            # Swap column i with the correct column
            table[0][i], table[0][table[0][i] - 1] = table[0][table[0][i] - 1], table[0][i]
            break
    else:
        # If no swap was made, it's not possible to sort the first row
        return "NO"

    # Check if the first row is now sorted
    if table[0] != list(range(1, m+1)):
        return "NO"

    # Try to sort the remaining rows by swapping elements within rows
    for row in table[1:]:
        for i in range(m - 1):
            if row[i] != i + 1:
                # Find the correct element in the row
                correct_index = row.index(i + 1)
                # Swap elements
                row[i], row[correct_index] = row[correct_index], row[i]
                break
        else:
            # If no swap was made, it's not possible to sort the row
            return "NO"

    # If all rows are sorted, return "YES"
    return "YES"


