def dfs(node, visited, s):
    visited[node] = True
    for i in graph[node]:
        if not visited[i]:
            s += "a" if i == node + 1 else "b" if i == node - 1 else "c"
            dfs(i, visited, s)
    return s

visited = [False] * (n + 1)
s = ""
for i in range(1, n + 1):
    if not visited[i]:
