def solve(grid, n, m):
    if n == 1 and m == 1:
        return 0
    if n == 1:
        return m
    if m == 1:
        return n
    min_moves = float('inf')
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 0:
                grid[i][j] = 1
                min_moves = min(min_moves, 1 + solve(grid, n - 1, m))
                grid[i][j] = 0
    for i in range(m):
        for j in range(n):
            if grid[j][i] == 0:
                grid[j][i] = 1
                min_moves = min(min_moves, 1 + solve(grid, n, m - 1))
                grid[j][i] = 0
    return min_moves

