def main():
    k, a, b = map(int, input().split())

    # If either A or B can't reach k points with their current score, it's impossible
    if a < k and b >= k or b < k and a >= k:
        print(-1)
    else:
        # The maximum number of sets is the minimum of (a//k, b//k) because each set ends when one player reaches k points
        max_sets = min(a // k, b // k)

        # If there's a remaining point for one of them after the last set, they would need to win the next set to make it possible
        if a % k != 0 and b >= k or b % k != 0 and a >= k:
            max_sets += 1

        print(max_sets)

