def stack_sortable(n, k, p):
    p = [0] + p + [n+1]
    p.sort()
    stack = []
    for i in range(1, len(p)):
        if p[i] < p[i-1]:
            stack.append(p[i-1])
            while stack and stack[-1] > p[i]:
                stack.pop()
    if stack:
        return -1
    else:
        p = p[1:-1]
        p.sort(reverse=True)
        return p

