def is_stack_sortable(arr):
    stack = []
    for num in arr:
        while stack and stack[-1] > num:
            stack.pop()
        stack.append(num)
    return stack == sorted(arr)

def restore_permutation(n, k, first_k_elements):
    remaining_elements = list(range(1, n+1))
    remaining_elements = [x for x in remaining_elements if x not in first_k_elements]

    # Try to construct the permutation by appending remaining elements
    for i in range(len(remaining_elements)):
        if is_stack_sortable(first_k_elements + remaining_elements[:i+1]):
            return first_k_elements + remaining_elements[:i+1]

    # If no permutation can be constructed, return -1
    return -1

