def minimumExtensions(h, w, n, a, b):
    # Initialize a dictionary to store the minimum number of extensions needed for each side
    extensions = {
        'width': {i: 0 for i in range(n)},
        'length': {i: 0 for i in range(n)}
    }

    # Iterate through the available extensions and calculate the minimum number of extensions needed for each side
    for i in range(n):
        for j in range(h):
            for k in range(w):
                # Calculate the new size of the field after applying the i-th extension
                new_h = h * a[i]
                new_w = w * a[i]

                # Check if the new size is smaller than the initial size
                if new_h <= h and new_w <= w:
                    # Increment the minimum number of extensions needed for the width or length side
                    extensions['width][i] += 1 if new_w < w else extensions['length][i] += 1

    # Return the minimum number of extensions needed for either the width or length side
    return min(extensions['width'].values()) if extensions['width'].any() else min(extensions['length'].values())

