    # Find the positions of S and T
    sx, sy = None, None
    tx, ty = None, None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                sx, sy = i, j
            elif grid[i][j] == 'T':
                tx, ty = i, j

    # Check if it is possible to reach T from S
    if not can_reach(grid, sx, sy, tx, ty):
        print(-1)
        return

    # Find the minimum number of leaves to remove
    min_leaves = float('inf')
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'o':
                # Remove the leaf at (i, j) and check if it is still possible to reach T from S
                grid[i][j] = '.'
                if not can_reach(grid, sx, sy, tx, ty):
                    min_leaves = min(min_leaves, 1)
                else:
                    # Restore the leaf at (i, j)
                    grid[i][j] = 'o'

