def find_common_number(n, m, first_pairs, second_pairs):
    common_numbers = set()
    for pair in first_pairs:
        if pair in second_pairs:
            common_numbers.add(pair[0])
            common_numbers.add(pair[1])

    if len(common_numbers) == 1:
        return common_numbers.pop()
    elif len(common_numbers) > 1:
        return 0
    else:
