import math

def minimum_time(m, h_1, a_1, x_1, y_1, h_2, a_2, x_2, y_2):
    # Calculate the modulo of two numbers
    def modulo(a, b):
        return a % b

    # Calculate the difference between the current height and the target height
    def difference(height, target):
        return height - target

    # Calculate the minimum time it takes for Xaniar to reach the target height
    def minimum_time_xaniar(height):
        return difference(height, a_1) // m

    # Calculate the minimum time it takes for Abol to reach the target height
    def minimum_time_abol(height):
        return difference(height, a_2) // m

    # Return the minimum time it takes for Xaniar or Abol to reach the target height
    return min(minimum_time_xaniar(h_1), minimum_time_abol(h_2))

# Example cases
