def kth_divisor(n, k):
    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        if mid * (mid + 1) // 2 < k:
            left = mid + 1
        else:
            right = mid
    if left * (left + 1) // 2 < k:
        return -1
    else:
        return left

