def find_kth_smallest_divisor(n, k):
    def count_divisors(num):
        count = 0
        i = 2
        while i * i <= num:
            if num % i:
                i += 1
            else:
                num //= i
                count += 1
        if num > 1:
            count += 1
        return count

    def smallest_divisor(num, k):
        divisors = []
        i = 2
        while i * i <= num:
            if num % i:
                i += 1
            else:
                while num % i == 0:
                    num //= i
                    divisors.append(i)
        if num > 1:
            divisors.append(num)

        divisors.sort()
        if len(divisors) < k:
            return -1
        else:
            return divisors[k - 1]

    n_divisors = count_divisors(n)
    if k > n_divisors:
        return -1
    else:
        return smallest_divisor(n, k)

