def count_apples(n, p):
    # Initialize a dictionary to keep track of the number of apples in each inflorescence
    apple_count = {i: 0 for i in range(n)}

    # Loop through each second, keeping track of the number of apples that roll down
    for _ in range(n):
        # Initialize a variable to keep track of the number of apples that will be collected
        collected = 0

        # Loop through each inflorescence, and keep track of the number of apples that will be collected
        for i in range(n):
            # If the apple in the current inflorescence is the first one, collect it
            if p[i] == 1:
                collected += 1
            # If the apple in the current inflorescence is not the first one, and it is not annihilated, collect it
            elif p[i] > 1 and not apple_count[i]:
                collected += 1

        # Update the number of apples in each inflorescence
        for i in range(n):
            apple_count[i] = apple_count[i] - collected

    return collected

