def count_ways(n, p, colors):
    def dfs(i, parity, memo):
        if i == n:
            return 1 if parity == p else 0
        if (i, parity) in memo:
            return memo[(i, parity)]
        total = 0
        for j in range(i + 1, n):
            if colors[i] != colors[j]:
                total += dfs(j, 1 - parity, memo)
        memo[(i, parity)] = total % (10**9 + 7)
        return memo[(i, parity)]

    memo = {}
    return dfs(0, 0, memo)

