def solve(n, p, colors):
    MOD = 10**9 + 7
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        if colors[i - 1] == 1:
            dp[i][0] = dp[i - 1][1]
            dp[i][1] = dp[i - 1][0]
        elif colors[i - 1] == 0:
            dp[i][0] = dp[i - 1][0]
            dp[i][1] = dp[i - 1][1]

    for k in range(2, n + 1):
        for i in range(n + 1 - k):
            j = i + k
            if colors[i] == 1 and colors[j] == 0:
                dp[i][j] = (dp[i][j] + dp[i + 1][j - 1]) % MOD
            elif colors[i] == 0 and colors[j] == 1:
                dp[i][j] = (dp[i][j] + dp[i + 1][j - 1]) % MOD
            else:
                dp[i][j] = (dp[i][j] + dp[i + 1][j - 1] + dp[i][j - 1]) % MOD

    # Calculate the number of ways with the desired parity
    total_ways = sum(dp[0][i] for i in range(n + 1))
    if p == 0:
        total_ways %= MOD
    else:
        total_ways = (MOD - total_ways) % MOD

    return total_ways


