from collections import defaultdict

def find_beautiful_rectangle(n, numbers):
    # Create a dictionary to store the indices of each number
    indices = defaultdict(list)
    for i, num in enumerate(numbers):
        indices[num].append(i)

    # Find the largest beautiful rectangle
    max_area = 0
    max_rectangle = []
    for num, idx_list in indices.items():
        if len(idx_list) < 2:
            continue

        # Try all possible combinations of rows and columns
        for i in range(len(idx_list)):
            for j in range(i + 1, len(idx_list)):
                row1, row2 = idx_list[i], idx_list[j]
                cols = set()
                for k in range(len(idx_list)):
                    if k != i and k != j:
                        cols.add(idx_list[k])
                if len(cols) >= 2:
                    area = 2 * len(cols)
                    if area > max_area:
                        max_area = area
                        max_rectangle = [numbers[row1], numbers[row2]] + sorted(numbers[i] for i in cols)

    # Print the output
    print(max_area)
    p, q = int(max_area ** 0.5), int(max_area // (max_area ** 0.5))
    print(p, q)
    for i in range(p):
        print(" ".join(map(str, max_rectangle[i*q:(i+1)*q])))

