import math

n = int(input())
strengths = list(map(int, input().split()))

if len(set(strengths)) == 1:
    print(n)
else:
    gcd_set = set()
    max_group_size = 0

    while len(gcd_set) < n:
        gcd = math.gcd(*strengths)
        if gcd not in gcd_set:
            gcd_set.add(gcd)
            max_group_size = max(max_group_size, len(list(filter(lambda x: gcd == math.gcd(x, gcd), strengths))))
            for i in range(n):
                if strengths[i] == gcd:
                    strengths.pop(i)
                    n -= 1
                    i -= 1

    print(n + len(gcd_set) - max_group_size)

