def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Check if it's possible to split the integers into two groups
    g1 = a[0]
    g2 = a[1]
    for i in range(2, n):
        if gcd(g1, a[i]) == 1:
            g1 = a[i]
        else:
            g2 = a[i]

    # If it's not possible, print "NO"
    if gcd(g1, g2) != 1:
        print("NO")
        return

    # Assign the integers to the two groups
    result = [0] * n
    for i in range(n):
        if gcd(a[i], g1) == 1:
            result[i] = 1
        else:
            result[i] = 2
    print("YES")
    print(*result)

