def is_coordinate_reachable(distances, directions, target):
    n = len(distances)
    dp = {0: {0: True}}
    for i in range(n):
        new_dp = {}
        for x in dp:
            for y in dp[x]:
                new_dp[x + distances[i]] = {y + distances[i]: True}
                new_dp[x - distances[i]] = {y + distances[i]: True}
                new_dp[x] = {y + distances[i]: True}
                new_dp[x + distances[i]] = {y: True}
        dp = new_dp

    return target in dp or -target in dp

