def dfs(node, parent, x):
    if node == 1:
        return 0
    else:
        return dfs(parent[node], parent, x) + x[node]


def dfs_color(node, parent, x, color, weight):
    if node == 1:
        return
    else:
        if color[node] == 0:
            color[node] = 1
            weight[node] = dfs(node, parent, x)
            dfs_color(parent[node], parent, x, color, weight)
        else:
            color[node] = 0
            weight[node] = dfs(node, parent, x)
            dfs_color(parent[node], parent, x, color, weight)


