def dfs(graph, start, visited):
    visited.add(start)
    for node in graph[start]:
        if node not in visited:
            dfs(graph, node, visited)

def get_paths(graph, start, end):
    visited = set()
    dfs(graph, start, visited)
    paths = []
    for node in visited:
        if node == end:
            paths.append(node)
        else:
            paths.append(node)
    return paths

