    while b:
        a, b = b, a % b
    return a

def find_numbers(divisors):
    divisors.sort()
    count = {d: 0 for d in divisors}
    for i in range(1, len(divisors)):
        if divisors[i] == divisors[i - 1]:
            count[divisors[i]] += 1
        else:
            if count[divisors[i]] % 2 == 1:
                x = divisors[i]
            else:
                g = gcd(count[divisors[i]] // 2, x)
                y = divisors[i] // g
                break
            count[divisors[i]] = 0

    x = y * pow(2, count[x], y)
    for d in divisors:
        if d != x and d != y:
            x *= d // gcd(x, d)

    return x, y

