    matrix_b = [[0 for _ in range(m)] for _ in range(n)]
    operations = []

    def set_submatrix_to_one(x, y):
        matrix_b[x][y] = 1
        matrix_b[x][y + 1] = 1
        matrix_b[x + 1][y] = 1
        matrix_b[x + 1][y + 1] = 1
        operations.append((x, y))

    for i in range(n):
        for j in range(m):
            if matrix_a[i][j] == 1:
                if matrix_b[i][j] == 0:
                    if i > 0 and j > 0 and matrix_b[i - 1][j - 1] == 0:
                        set_submatrix_to_one(i - 1, j - 1)
                    else:
                        return -1  # Cannot make matrices equal

    return len(operations), operations


