import sys

def solve(s):
    n = len(s)
    colors = [0] * n
    color_set = set()

    # Check if it is possible to color the characters one of the two colors
    for i in range(n):
        if s[i] in color_set:
            continue
        color_set.add(s[i])
        colors[i] = 1
        for j in range(i + 1, n):
            if s[j] in color_set and colors[j - 1]!= colors[i]:
                colors[j - 1] = colors[i] ^ 1
                break

    # Check if the characters can be sorted using swaps
    for i in range(1, n):
        if colors[i - 1]!= colors[i] and s[i - 1] > s[i]:
            return False

    # If the above conditions are met, then a coloring exists that sorts the characters
    if colors[-1] == 1:
        return "YES"
    else:
        return "NO"

def main():
    n = int(input())
    s = input()
    result = solve(s)
    print(result)

