def can_construct_square(tiles, m):
    n = len(tiles) // 2
    matrix = [[0] * m for _ in range(m)]

    def backtrack(row, col):
        if row == m:
            return is_symmetric(matrix)

        if col == m:
            return backtrack(row + 1, 0)

        for tile_idx in range(n):
            top_left, top_right, bottom_left, bottom_right = tiles[tile_idx * 2], tiles[tile_idx * 2 + 1], tiles[n * 2 + tile_idx * 2], tiles[n * 2 + tile_idx * 2 + 1]
            if matrix[row][col] == 0 and matrix[col][row] == 0:
                matrix[row][col] = top_left
                matrix[col][row] = top_right
                matrix[row][m - 1 - col] = bottom_left
                matrix[m - 1 - col][row] = bottom_right
                if backtrack(row, col + 1):
                    return True
                matrix[row][col] = 0
                matrix[col][row] = 0
                matrix[row][m - 1 - col] = 0
                matrix[m - 1 - col][row] = 0
        return False

    return backtrack(0, 0)

