def max_sum_divisible_by_k(n, m, k, matrix):
    max_sum = 0
    for row in matrix:
        # Create all possible combinations of elements in the row
        combinations = []
        for i in range(len(row) + 1):
            for subset in itertools.combinations(row, i):
                combinations.append(sum(subset))

        # Find the maximum sum divisible by k
        for subset_sum in combinations:
            if subset_sum % k == 0 and subset_sum > max_sum:
                max_sum = subset_sum

    return max_sum

