    # Initialize a dictionary to store the available rating after completing each project
    available_rating = {i: r for i in range(n)}

    # Loop through the projects and check if the rating is sufficient for each one
    for i in range(n):
        a = int(input())
        b = int(input())
        if available_rating[i] < a:
            print("NO")
            return
        available_rating[i] -= b
        if available_rating[i] < 0:
            print("NO")
            return
    print("YES")

