def is_aesthetic(n):
    for i in range(1, n):
        for j in range(i+1, n+1):
            if abs(i-j) % n == 0 and i != j:
                return False
    return True


def get_max_colors(n):
    if is_aesthetic(n):
        return n
    else:
        for i in range(1, n):
            if is_aesthetic(i):
                return get_max_colors(n-i)


