import random
import math
def prob(r,s,p):
    if r==0:
        return 0
    if s==0:
        return 1
    if p==0:
        return 2
    if r==1:
        return 1/3
    if s==1:
        return 1/3
    if p==1:
        return 1/3
    return prob(r-1,s,p)+prob(r,s-1,p)+prob(r,s,p-1)
r,s,p=map(int,input().split())
print(prob(r,s,p))

def calculate_probabilities(r, s, p):
    dp = [[[0.0 for _ in range(p+1)] for _ in range(s+1)] for _ in range(r+1)]

    for i in range(r+1):
        for j in range(s+1):
            for k in range(p+1):
                if i == 0 and j == 0:
                    dp[i][j][k] = 0
                elif i == 0 and k == 0:
                    dp[i][j][k] = 1
                elif j == 0 and k == 0:
                    dp[i][j][k] = 1
                else:
                    total = i*j + j*k + k*i
                    dp[i][j][k] = (i*j + dp[i-1][j][k]) / total + (j*k + dp[i][j-1][k]) / total + (k*i + dp[i][j][k-1]) / total

    return dp[r][s][p], dp[s][p][r], dp[p][r][s]

r, s, p = map(int, input().split())
result = calculate_probabilities(r, s, p)
