def roman_to_int(roman):
    roman_dict = {"I": 1, "V": 5, "X": 10, "L": 50}
    int_dict = {1: "I", 5: "V", 10: "X", 50: "L"}
    result = 0
    for i in range(len(roman)):
        if i < len(roman) - 1 and roman_dict[roman[i]] < roman_dict[roman[i + 1]]:
            result -= roman_dict[roman[i]]
        else:
            result += roman_dict[roman[i]]
    return result


