def find_path(N, board):
    directions_knight = [(2, 1), (2, -1), (1, 2), (1, -2), (-2, 1), (-2, -1), (-1, 2), (-1, -2)]
    directions_bishop = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
    directions_rook = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def is_valid_move(piece, current_pos, target_pos, visited):
        if piece == 'knight':
            return target_pos in directions_knight[current_pos]
        elif piece == 'bishop':
            return target_pos in directions_bishop[current_pos]
        elif piece == 'rook':
            return target_pos in directions_rook[current_pos]
        return False

    def find_next_move(current_pos, target_square, visited, piece):
        moves = []
        for i in range(N):
            for j in range(N):
                if i != current_pos[0] or j != current_pos[1]:
                    if is_valid_move(piece, current_pos, (i, j), visited):
                        moves.append((i, j))
        if not moves:
            return None
        min_moves = float('inf')
        best_move = None
        for move in moves:
            new_visited = set(visited)
            new_visited.add(move)
            if move == target_square:
                return 1, 0
            temp_steps, temp_replacements = find_path(N, board, new_visited, move, target_square)
            if temp_steps < min_moves:
                min_moves = temp_steps
                best_move = move
        return min_moves + 1, temp_replacements + 1

    def bfs(start, end):
        queue = [(start, 0, 0)]  # (position, steps, replacements)
        visited = set([start])
        while queue:
            current_pos, steps, replacements = queue.pop(0)
            if current_pos == end:
                return steps, replacements
            for piece in ['knight', 'bishop', 'rook']:
                next_steps, next_replacements = find_next_move(current_pos, end, visited, piece)
                if next_steps is not None:
                    queue.append((next_steps, steps + next_steps, replacements + next_replacements))
                    visited.add(next_steps)
        return float('inf'), float('inf')

    start_pos = None
    end_pos = None
    for i in range(N):
        for j in range(N):
            if board[i][j] == 1:
                start_pos = (i, j)
            if board[i][j] == N*N:
                end_pos = (i, j)

    steps, replacements = bfs(start_pos, end_pos)
    print(steps, replacements)

