def find_k(n):
    # Initialize a dictionary to keep track of the number of people in each flat
    people = {i: 0 for i in range(n)}
    for i in range(n):
        if a[i]:
            people[i] += 1

    # Find the minimum number of people that can turn off their lights without disturbing anyone
    minimum_k = n
    for k in range(1, n):
        # Check if there are enough people in the house to turn off their lights without disturbing anyone
        if people[k] >= k:
            # If there are enough people, check if turning off lights in k flats will disturb anyone
            for i in range(k):
                if people[i] == 0:
                    # If turning off lights in this flat will disturb someone, then the minimum number of people needed is k-1
                    minimum_k = k - 1
                    break
            else:
                # If no one is disturbed, then the minimum number of people needed is k
                minimum_k = k
    return minimum_k

