def minimum_heaters(n, r):
    # Initialize a dictionary to keep track of the number of heaters used for each position
    used_heaters = {i: 0 for i in range(n)}

    # Iterate through the array and find the minimum number of heaters needed to warm up each position
    for i in range(n):
        if a[i]:
            # If the current position has a heater, check if it can warm up the entire position
            if i + r - 1 < n and a[i + r - 1]:
                # If the position can be warmed up, update the number of heaters used for that position
                used_heaters[i + r - 1] += 1
            # Otherwise, check if there is a heater in the next position that can warm up the current position
            elif i + r < n and a[i + r]:
                used_heaters[i + r] += 1

    # Return the minimum number of heaters used
    return min(used_heaters.values())

