def find_max_number_of_problems(n, difficulties):
    # Initialize a dictionary to store the number of valid contests for each number of problems
    contests = {1: 0, 2: 0, 3: 0, 4: 0}

    # Iterate over the difficulties and find the number of valid contests for each number of problems
    for difficulty in difficulties:
        for i in range(n):
            if difficulties[i] <= difficulty * 2:
                # Increase the number of valid contests for the current difficulty
                contests[i + 1] += 1

    # Return the maximum number of problems in the valid contests
    return max(contests.values())

