def count_regular_bracket_sequences(n, s):
    mod = 10**9 + 7
    dp = [0] * (2 * n + 1)
    dp[0] = 1

    open_count = 0
    for i in range(len(s)):
        if s[i] == '(':
            open_count += 1

    for i in range(n, -1, -1):
        if s[open_count] == ')':
            dp[i] = sum(dp[j + 1] for j in range(i, i + open_count + 1) if s[j] == '(' and s[j + open_count] == ')') % mod
        else:
            dp[i] = dp[i + 1]

    return dp[0]

