def main():
    # Read input
    N, M = map(int, input().split())
    switches = [[] for _ in range(N + 1)]
    bulbs = [[] for _ in range(M + 1)]
    for i in range(1, M + 1):
        k, *s = map(int, input().split())
        bulbs[i] = s
        for j in s:
            switches[j].append(i)
    p = list(map(int, input().split()))

    # Calculate the number of combinations
    ans = 0
    for i in range(1 << N):
        state = [0] * (N + 1)
        for j in range(N):
            if (i >> j) & 1:
                state[j + 1] = 1
        cnt = [0] * (M + 1)
        for j in range(1, N + 1):
            if state[j]:
                for k in switches[j]:
                    cnt[k] += 1
        flag = True
        for j in range(1, M + 1):
            if cnt[j] % 2 != p[j - 1]:
                flag = False
                break
        if flag:
            ans += 1

    # Print the answer
    print(ans)

