def min_length_after_abbreviation(n, words):
    words_len = [len(word) for word in words]
    segments = {}
    prefix_len = 0

    for i in range(n):
        current_prefix = words[i][:prefix_len]
        if current_prefix in segments:
            segments[current_prefix].append(i)
        else:
            segments[current_prefix] = [i]

        if i > 0 and words[i] == words[i - 1]:
            prefix_len += 1
        else:
            prefix_len = 0

    min_len = sum(words_len)
    for prefix, indices in segments.items():
        if len(indices) >= 2:
            abbreviation_len = len(prefix) + (len(indices) - 1)
            for i in range(1, len(indices)):
                min_len = min(min_len, sum(words_len[indices[j]:indices[j+1]] for j in range(len(indices)-1)) + abbreviation_len)

    return min_len

