def find_most_frequent_twogram(s):
    # Initialize a dictionary to count the frequency of each two-gram
    freq = {}
    for i in range(len(s)):
        for j in range(i+1, len(s)):
            if s[i] == s[j]:
                freq[s[i] + s[j]] += 1
    # Find the most frequent two-gram
    most_frequent = None
    most_freq = 0
    for k, v in freq.items():
        if v > most_freq:
            most_frequent = k
            most_freq = v
    return most_frequent

