def min_subsegment_size(arr):
    n = len(arr)
    if n <= 1:
        return 0

    counter = {}
    duplicates = 0
    start = 0

    for end, value in enumerate(arr):
        if value in counter:
            duplicates += 1
            while counter[value] >= start:
                del counter[arr[start]]
                start += 1
            counter[value] = end
        else:
            counter[value] = end

    return duplicates

