n, k = map(int, input().split())
s = input()

def is_subsequence(s, t):
    i = 0
    for c in s:
        if i >= len(t):
            return False
        if s[i] == t[i]:
            i += 1
    return i == len(t)

def min_cost(s, k):
    if k == 0:
        return 0
    if k == 1:
        return n
    if k == 2:
        return n - 1
    if k >= len(s):
        return 0
    if k == 1:
        return n
    min_cost = float('inf')
    for i in range(1, len(s)):
        if is_subsequence(s[:i], s[i:]):
            min_cost = min(min_cost, min_cost(s[i:], k - 1) + n - i)
    return min_cost

print(min_cost(s, k))

def min_cost_to_obtain_set(n, k, s):
    dp = [[0] * (n+1) for _ in range(k+1)]

    for i in range(1, n+1):
        dp[1][i] = i

    for i in range(2, k+1):
        for j in range(1, n+1):
            min_cost = float('inf')
            for l in range(1, j+1):
                min_cost = min(min_cost, dp[i-1][j-l] + (j-l))
            dp[i][j] = min_cost

    if dp[k][n] == float('inf'):
        return -1
    else:
        return dp[k][n]

n, k = map(int, input().split())
s = input()
result = min_cost_to_obain_set(n, k, s)
print(result)

def find_min_cost(n, k, s):
    if k == 0:
        return 0
    if n == 0:
        return -1
    if k > n:
        return -1
    dp = [float('inf')] * (k + 1)
    dp[0] = 0
    for i in range(n):
        for j in range(1, k + 1):
            if j >= len(s) or s[i] not in s[:j]:
                dp[j] = min(dp[j], dp[j - len(s) + 1] + (1 if s[i] in s[:j] else -1))
    return dp[k] if dp[k] != float('inf') else -1

# Test cases
print(find_min_cost(4, 5, "asdf")) # Output: 4
print(find_min_cost(5, 6, "aaaaa")) # Output: 15
print(find_min_cost(5, 7, "aaaaa")) # Output: -1
print(find_min_cost(10, 100, "ajihiushda")) # Output: 233

