n = int(input())

if n <= 1:
    print("Vasya")
else:
    # Initialize a dictionary to keep track of the powers of each number
    powers = {}
    for i in range(n):
        powers[i] = set()

    # Play the game
    while True:
        # Choose a number at random
        number = random.randint(2, n)

        # Check if the number and its powers are already taken
        if number in powers or any(powers[x] and number ** x in powers for x in powers):
            # If the number and its powers are already taken, choose another number
            continue

        # Add the number and its powers to the dictionary
        powers[number] = set()
        for x in range(number):
            powers[number].add(x ** number)

        # Print the winner
        if not powers:
            print("Vasya")
            break
        else:
            print("Petya")

    # If the game is still ongoing, the winner is Petya

