import sys

def median(arr):
    arr.sort()
    n = len(arr)
    if n % 2 == 0:
        return (arr[n // 2 - 1] + arr[n // 2]) / 2
    else:
        return arr[n // 2]

def count_pairs(arr, m):
    n = len(arr)
    count = 0
    for i in range(n):
        for j in range(i, n):
            sub_arr = arr[i:j+1]
            if median(sub_arr) == m:
                count += 1
    return count

