n = int(input())
path = [int(x) for x in input().split()]

# calculate the maximum possible matrix size
x_max = max(path)
y_max = max(set(path) - set(range(1, x_max+1)))

# try all possible combinations of x and y sizes
for x in range(1, x_max+1):
    for y in range(1, y_max+1):
        # check if the matrix can be filled with the given path
        visited = set()
        i, j = 0, 0
        while i < n:
            # check if the current cell is valid
            if (i, j) not in visited and 1 <= path[i-1] <= x*y:
                visited.add((i, j))
                # move to the next cell
                if i < n-1 and (i+1, j) not in visited:
                    i += 1
                elif j < y-1 and (i, j+1) not in visited:
                    j += 1
                elif i > 0 and (i-1, j) not in visited:
                    i -= 1
                elif j > 0 and (i, j-1) not in visited:
                    j -= 1
            else:
                break
        # if the matrix can be filled with the path, print the solution
        if len(visited) == n:
            print("YES")
            print(x, y)
            break
else:
    # if no solution exists, print NO
    print("NO")

