import sys
from collections import defaultdict

def dfs(v, visited, graph):
    visited[v] = True
    for u in graph[v]:
        if not visited[u]:
            dfs(u, visited, graph)

def main():
    n, m, q = map(int, input().split())
    graph = defaultdict(list)
    for _ in range(q):
        r, c = map(int, input().split())
        graph[r].append(n + c)
        graph[n + c].append(r)
    visited = [False] * (n + m + 1)
    components = 0
    for v in range(1, n + m + 1):
        if not visited[v]:
            dfs(v, visited, graph)
            components += 1
    print(components - 1)

if __name__ == "__main__":
    sys.setrecursionlimit(10**6)
    main()

def min_purchases(n, m, elements):
    table = set()
    for r, c in elements:
        table.add((r, c))

    missing = set()
    for r in range(1, n+1):
        for c in range(1, m+1):
            if (r, c) not in table:
                missing.add((r, c))

    queue = list(missing)
    purchases = 0

    while queue:
        r, c = queue.pop(0)
        if not can_produce(n, m, table, r, c):
            purchases += 1
            continue

        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr <= n and 0 <= nc <= m and (nr, nc) not in table:
                    queue.append((nr, nc))
                    table.add((nr, nc))

    return purchases

def can_produce(n, m, table, r, c):
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        if 0 <= r+dr <= n and 0 <= c+dc <= m and (r+dr, c+dc) in table:
            return True
    return False

