def longest_subsequence(s, t):
    s_index = 0
    length = 0
    for char in t:
        while s[s_index] != char:
            if s_index == 0 or s[s_index-1] != s[s_index-1]:
                s_index += 1
            else:
                s_index -= 1
        length += 1
        s_index += 1
    return len(s) - length

