def max_substring_to_remove(s, t):
    n = len(s)
    m = len(t)

    prefix = [0] * m
    suffix = [0] * m

    j = 0
    for i in range(n):
        if s[i] == t[j]:
            prefix[j] = i
            j += 1
            if j == m:
                break

    j = m - 1
    for i in range(n-1, -1, -1):
        if s[i] == t[j]:
            suffix[j] = i
            j -= 1
            if j == -1:
                break

    max_len = max(suffix[0], n - prefix[m-1] - 1)
    for i in range(m-1):
