def minimal_layers(N):
    segments = [(i, j) for i in range(N + 1) for j in range(i, N + 1)]
    layers = []

    def can_add_segment(segment, existing_segments):
        for es in existing_segments:
            if es[0] <= segment[0] <= es[2] or es[0] <= segment[1] <= es[2]:
                return False
        return True

    for segment in segments:
        added = False
        for i, layer in enumerate(layers):
            if can_add_segment(segment, layer):
                layers[i].append(segment)
                added = True
                break
        if not added:
            layers.append([segment])

    return len(layers)

