def cards_war(k1, a1, k2, a2):
    n = k1 + k2
    if n % 2 == 0:
        return -1
    if k1 > k2:
        return cards_war(k2, a2, k1, a1)
    if k1 == k2:
        if a1[0] > a2[0]:
            return 2
        elif a1[0] < a2[0]:
            return 1
        else:
            return -1
    if k1 > 0:
        if a1[0] > a2[k2 - 1]:
            return 2
        elif a1[0] < a2[k2 - 1]:
            return cards_war(k1 - 1, a1[1:], k2, a2)
        else:
            return cards_war(k1 - 1, a1[1:], k2, a2)

