def main():
    N, M = map(int, input().split())
    cities = [list(map(int, input().split())) for _ in range(M)]
    cities.sort(key=lambda x: (x[0], x[1]))

    prefecture_cities = {}
    for i, (prefecture, year) in enumerate(cities):
        if prefecture not in prefecture_cities:
            prefecture_cities[prefecture] = []
        prefecture_cities[prefecture].append(i+1)

    for i, (prefecture, year) in enumerate(cities):
        prefecture_cities[prefecture][i] = str(prefecture).zfill(6) + str(prefecture_cities[prefecture].index(i+1)+1).zfill(6)

    for i in range(1, N+1):
        if i in prefecture_cities:
            for city in prefecture_cities[i]:
                print(city)
        else:
            print('0'*12)

