        # Replace every occurrence of c_2 with c_1 in T
        for i in range(len(T)):
            if c_2 in T[i]:
                T[i] = c_1

        # Check if S and T are now equal
        if s_letters == t_letters:
            return True

    # S and T are not equal, return False
    return False

def choose_letters(letters):
    # Choose two distinct letters from the set of letters
    c_1, c_2 = None, None
    for letter in letters:
        if c_1 is None or letter != c_1:
            c_1 = letter
        if c_2 is None or letter != c_2:
            c_2 = letter
    return c_1, c_2

