def get_divisors(n):
    divisors = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n / i:
                divisors.append(n / i)
    return divisors

def get_min_x(divisors):
    min_x = 1
    for i in range(1, 1000000):
        if isPrime(i):
            continue
        if all(i % divisor == 0 for divisor in divisors):
            min_x = i
            break
    return min_x

