def solve(t, w, b):
    lcm_val = lcm(w, b)
    total_possible_steps = t // lcm_val
    willman_steps = t // w
    bolt_steps = t // b
    common_steps = t // lcm_val

    total_tie_steps = willman_steps + bolt_steps - 2 * common_steps

    common_divisor = gcd(total_tie_steps, total_possible_steps)

    return f"{total_tie_steps // common_divisor}/{total_possible_steps // common_divisor}"

