from collections import defaultdict

def dfs(node, parent, graph, white, black):
    white_dist = 0
    black_dist = 0
    for neighbor in graph[node]:
        if neighbor != parent:
            w, b = dfs(neighbor, node, graph, white, black)
            white_dist = max(white_dist, w + 1)
            black_dist = max(black_dist, b + 1)
    if node in white:
        return white_dist, 0
    elif node in black:
        return 0, black_dist
    else:
        return white_dist, black_dist

def solve():
    N = int(input())
    graph = defaultdict(list)
    for _ in range(N - 1):
        a, b = map(int, input().split())
        graph[a].append(b)
        graph[b].append(a)

    total_niceness = 0
    for i in range(2 ** N):
        white = set()
        black = set()
        for j in range(N):
            if (i >> j) & 1:
                white.add(j + 1)
            else:
                black.add(j + 1)
        w, b = dfs(1, 0, graph, white, black)
        total_niceness = (total_niceness + max(w, b)) % (10 ** 9 + 7)

    print(total_niceness)

solve()

