mod = 10**9 + 7

def fastpow(x, p):
    if p == 0:
        return 1
    if p == 1:
        return x
    val = fastpow(x, int(p / 2)) % mod
    val = (val * val) % mod
    if p % 2 != 0:
        val = (val * x) % mod
    return val % mod

