def solve(S):
    # dp[i] := the number of ways to represent i as a sum of digits
    dp = [0] * (S + 1)
    dp[0] = 1
    for i in range(1, S + 1):
        for j in range(1, 10):
            if i - j >= 0:
                dp[i] += dp[i - j]
                dp[i] %= mod
    return dp[S]

