import math

def countPairs(S):
    # calculate the number of digits in base 10
    n = int(math.log10(S)) + 1

    # count the number of pairs of positive integers (l, r) that satisfy the condition
    count = 0
    for i in range(1, 10):
        for j in range(i, 10):
            if i * j <= S:
                count += (S // (i * j)) * (S // (i * j + 1))

    # return the count modulo 10^9 + 7
    return count % (10**9 + 7)

