def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def lcm(a, b):
    return (a * b) // gcd(a, b)

def find_optimal_k(a, b):
    if a == b:
        return 0

    # Find the greatest common divisor (gcd) of a and b
    gcd_ab = gcd(a, b)

    # The optimal k will be the difference between a and b divided by their gcd, then rounded up to the nearest integer
    k = ((a - b) // gcd_ab) + 1

    # Calculate the least common multiple (lcm) for a+k and b+k
    lcm_a_k = lcm(a + k, b + k)

    # Check if there's a smaller lcm for a different k
    for i in range(1, k):
        new_lcm = lcm(a + i, b + i)
        if new_lcm < lcm_a_k:
            lcm_a_k = new_lcm
            k = i

    return k

