def ravioli_sort(arr):
    stacks = [[] for _ in arr]
    for num in arr:
        for _ in num:
            stacks[arr.index(num)].append(1)

    while len(stacks) > 1:
        max_stack = stacks[0]
        max_index = 0
        for i in range(1, len(stacks)):
            if len(stacks[i]) > len(max_stack):
                max_stack = stacks[i]
                max_index = i

        if max_stack[0] - len(max_stack) > 1:
            return "NO"

        output.append(len(max_stack))
        del stacks[max_index]
        for stack in stacks:
            stack.append(stack.pop(0))

    return "YES" if not arr else ravioli_sort(output)

