def spaghetti(a):
    stack = []
    for i in a:
        stack.append([i, 0])
    while len(stack) > 1:
        max_height = 0
        max_index = 0
        for i in range(len(stack)):
            if stack[i][1] > max_height:
                max_height = stack[i][1]
                max_index = i
        if max_height > stack[max_index][1]:
            stack[max_index][1] = max_height + 1
        else:
            stack[max_index][1] = max_height
    return stack[0][0]


