def min_time_to_eat_all_asterisks(n, game_field):
    packmen_positions = [i for i, cell in enumerate(game_field) if cell == 'P']
    asterisks_positions = [i for i, cell in enumerate(game_field) if cell == '*']

    min_time = float('inf')
    for packman_pos in packmen_positions:
        for asterisk_pos in asterisks_positions:
            time = abs(packman_pos - asterisk_pos)
            if time < min_time:
                min_time = time

    return min_time

