def find_teams(n):
    def check(x):
        # Calculate the total number of games for x teams
        stages = 0
        while x % 2 == 0:
            x //= 2
            stages += 1
        # Round-robin tournament for odd number of teams
        remaining_games = x * (x - 1) // 2
        return stages * (x // 2) + remaining_games == n

    # Start from 3 (since 1 and 2 teams won't need n games)
    for i in range(3, int(n**0.5) + 1):
        if check(i):
            print(i)
    # Check for cases where n is a perfect square
    if n % 2 == 0 and check(int(n**0.5)):
        print(int(n**0.5))
    # If no solution found, print -1
    if not any(check(i) for i in range(3, int(n**0.5) + 1) if i % 2 == 0):
        print(-1)

