    step = 1
    direction = 0

    while n >= step:
        for _ in range(2):
            if direction == 0:
                x += step
            elif direction == 1:
                y += step
            elif direction == 2:
                x -= step
            else:
                y -= step
            n -= step
            direction = (direction + 1) % 4
        step += 1

    return x, y

