import math

def max_area_of_smallest_piece(n, m, k):
    if k > 2 * (n + m - 2):
        return -1

    min_area = float('inf')
    for i in range(1, n):
        for j in range(1, m):
            if k >= i + j - 1:
                area = min(i * j, (n - i) * j, i * (m - j), (n - i) * (m - j))
                min_area = min(min_area, area)
    return min_area

# Read input
n, m, k = map(int, input().split())

# Solve the problem
result = max_area_of_smallest_piece(n, m, k)
print(result)

def max_smallest_piece(n, m, k):
    if k > (n * m) // 2:
        return -1

    # Create a 2D boolean grid to mark the position of cuts
    grid = [[False] * m for _ in range(n)]

    # Perform cuts
    for _ in range(k):
        x, y = map(int, input().split())
        if x < n and y < m and not grid[x][y]:
            grid[x][y] = True
            for i in range(x + 1, n):
                grid[i][y] = True
                if m - y < i - x + 1:
                    break
            for i in range(x - 1, -1, -1):
                grid[i][y] = True
                if i - x < y + 1:
                    break
            for i in range(y + 1, m):
                grid[x][i] = True
                if i - y < x + 1:
                    break
            for i in range(x - 1, -1, -1):
                grid[x][i] = True
                if i - x < m - i:
                    break

    # Find the smallest piece
    min_area = float('inf')
    for i in range(n):
        for j in range(m):
            area = 1
            while grid[i][j]:
                i += 1 if grid[i][j] else i - 1
                j += 1 if grid[i][j] else j - 1
                area += 1
            min_area = min(min_area, area)

    return min_area

