def count_perfectly_balanced_striped_bst(n):
    # Memoization table to store the number of perfectly balanced striped BSTs with given number of vertices
    dp = [[0] * 2 for _ in range(n + 1)]

    # Base case: empty tree
    dp[0][0] = 1

    # Recursive function to calculate the number of perfectly balanced striped BSTs with given number of vertices
    def bst(x, parity):
        if x > n:
            return 0

        count = dp[x][parity]

        # If x is a leaf node
        if x == 1:
            count += 1

        # If x is an odd node
        if parity == 0:
            for key in range(1, x):
                if (x - key) % 2 == 1:
                    count += bst(x - key - 1, 1)

        # If x is an even node
        else:
            for key in range(1, x):
                if (x - key) % 2 == 0:
                    count += bst(x - key - 1, parity)

        return count % 998244353

    return bst(n, 0)

