    MOD = 998244353

    # Base cases
    if n == 1:
        return 1
    if n == 2:
        return 1
    if n == 3:
        return 0

    # Dynamic programming
    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 1

    for i in range(3, n + 1):
        for j in range(1, i // 2 + 1):
            if (i - j) % 2 != j % 2:
                dp[i] = (dp[i] + dp[j] * dp[i - j]) % MOD

