MOD = 1000000007

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def f(n):
    if n == 1:
        return 1
    count = 0
    for x in range(1, n):
        if gcd(x, n - x) == 1:
            count += 1
    return count

def g(n):
    divisors = [i for i in range(1, int(n**0.5) + 1) if n % i == 0]
    divisors.append(n)
    result = 0
    for d in divisors:
        result += f(n // d)
        result %= MOD
    return result

def F_k(n, k):
    if k == 1:
        return f(g(n)) % MOD
    elif k % 2 == 0:
        return g(F_k(n, k - 1)) % MOD
    else:
        return f(F_k(n, k - 1)) % MOD

# Input
n, k = map(int, input().split())

# Output
print(F_k(n, k))

