def dijkstra(source, destination):
    distances = [[inf for _ in range(n)] for _ in range(n)]
    distances[source[0]][source[1]] = 0
    visited = [[0 for _ in range(n)] for _ in range(n)]

    queue = deque()
    queue.append((source, 0))

    while queue:
        current_cell, current_distance = queue.popleft()

        if current_cell == destination:
            return current_distance

        for row in range(n):
            for col in range(n):
                if desert[row][col] and distances[row][col] > distances[current_cell[0]][current_cell[1]] + 1:
                    distances[row][col] = distances[current_cell[0]][current_cell[1]] + 1
                    prev_cell = (current_cell[0], current_cell[1])
                    queue.append((row, col))

    return -1

